CREATE OR REPLACE FUNCTION public.assign_pos_order_to_location(p_business_id uuid, p_order_id uuid, p_location_id uuid, p_shift_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_item record; v_role text; v_shift public.cash_register_shifts%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required.'; end if;
  select bm.role::text into v_role from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.is_active=true limit 1;
  if v_role is null then raise exception 'Not authorized for this business.'; end if;
  if not exists(select 1 from public.business_locations where id=p_location_id and business_id=p_business_id and is_active=true) then raise exception 'Branch not found.'; end if;
  if not exists(select 1 from public.orders where id=p_order_id and business_id=p_business_id) then raise exception 'Order not found.'; end if;
  if p_shift_id is not null then
    select * into v_shift from public.cash_register_shifts where id=p_shift_id and business_id=p_business_id and location_id=p_location_id and status='open';
    if not found then raise exception 'Open register shift does not match this branch.'; end if;
    if v_role='cashier' and v_shift.opened_by<>auth.uid() then raise exception 'Cashier shift mismatch.'; end if;
  end if;
  update public.orders set location_id=p_location_id,register_shift_id=p_shift_id where id=p_order_id and business_id=p_business_id;
  for v_item in select oi.product_id,sum(oi.quantity)::integer qty from public.order_items oi join public.products p on p.id=oi.product_id and p.business_id=p_business_id where oi.order_id=p_order_id and oi.product_id is not null group by oi.product_id loop
    insert into public.product_location_stock(business_id,location_id,product_id,quantity) values(p_business_id,p_location_id,v_item.product_id,0) on conflict(location_id,product_id) do nothing;
    update public.product_location_stock set quantity=greatest(0,quantity-v_item.qty),updated_at=now() where business_id=p_business_id and location_id=p_location_id and product_id=v_item.product_id;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.checkout_order_with_options(p_business_id uuid, p_items jsonb, p_payment_method text, p_amount_paid numeric, p_customer_id uuid DEFAULT NULL::uuid, p_discount numeric DEFAULT 0, p_delivery_fee numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- TENH_PROMOTIONS_V1
declare
  v_user_id uuid := auth.uid();
  v_business public.businesses%rowtype;
  v_member public.business_members%rowtype;
  v_item jsonb;
  v_product public.products%rowtype;
  v_product_id uuid;
  v_quantity integer;
  v_option_ids uuid[];
  v_selected_options jsonb;
  v_option_total numeric(12,2);
  v_unit_price numeric(12,2);
  v_line_subtotal numeric(12,2);
  v_subtotal numeric(12,2) := 0;
  v_discount numeric(12,2) := greatest(0, coalesce(p_discount, 0));
  v_delivery_fee numeric(12,2) := greatest(0, coalesce(p_delivery_fee, 0));
  v_total numeric(12,2);
  v_amount_paid numeric(12,2) := coalesce(p_amount_paid, 0);
  v_change numeric(12,2) := 0;
  v_remaining numeric(12,2) := 0;
  v_payment_status text;
  v_payment_method text := lower(coalesce(nullif(btrim(p_payment_method), ''), 'cod'));
  v_group record;
  v_group_selection_count integer;
  v_invalid_option_count integer;
  v_variant_label text;
  v_computed_items jsonb := '[]'::jsonb;
  v_computed jsonb;
  v_requested_by_product jsonb := '{}'::jsonb;
  v_requested_quantity integer;
  v_order_id uuid;
  v_order_number text;
begin
  if v_user_id is null then
    raise exception 'Your login session has expired.';
  end if;

  select * into v_business
  from public.businesses
  where id = p_business_id
  limit 1;

  if not found or not v_business.is_active then
    raise exception 'Business not found or inactive.';
  end if;

  select * into v_member
  from public.business_members
  where business_id = v_business.id
    and user_id = v_user_id
    and is_active = true
  limit 1;

  if not found then
    raise exception 'You no longer have access to this business.';
  end if;

  if v_business.subscription_expires_at is not null
     and v_business.subscription_expires_at <= now() then
    raise exception 'This business subscription has expired.';
  end if;

  if p_items is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0 then
    raise exception 'Your cart is empty.';
  end if;

  if jsonb_array_length(p_items) > 100 then
    raise exception 'Too many items in one order.';
  end if;

  if v_payment_method not in ('cod', 'deposit', 'bank_transfer', 'other') then
    raise exception 'Invalid payment method.';
  end if;

  if v_amount_paid < 0 then
    raise exception 'Invalid payment amount.';
  end if;

  if p_discount is null or p_delivery_fee is null or p_discount < 0 or p_delivery_fee < 0 then
    raise exception 'Discount and delivery fee cannot be negative.';
  end if;

  if p_customer_id is not null and not exists (
    select 1
    from public.customers
    where id = p_customer_id
      and business_id = v_business.id
  ) then
    raise exception 'Customer not found for this business.';
  end if;

  for v_item in
    select value from jsonb_array_elements(p_items)
  loop
    begin
      v_product_id := (v_item ->> 'productId')::uuid;
      v_quantity := (v_item ->> 'quantity')::integer;
    exception when others then
      raise exception 'The cart contains invalid product data.';
    end;

    if v_quantity is null or v_quantity < 1 or v_quantity > 999 then
      raise exception 'Invalid product quantity.';
    end if;

    select * into v_product
    from public.products
    where id = v_product_id
      and business_id = v_business.id
      and is_active = true
    for update;

    if not found then
      raise exception 'A product in your cart is no longer available.';
    end if;

    v_product:=public.tenh_pos_priced_product(v_product); v_requested_quantity :=
      coalesce((v_requested_by_product ->> v_product.id::text)::integer, 0)
      + v_quantity;

    if coalesce(v_product.stock_quantity, 0) < v_requested_quantity then
      raise exception 'Not enough stock for %.', v_product.name;
    end if;

    v_requested_by_product := jsonb_set(
      v_requested_by_product,
      array[v_product.id::text],
      to_jsonb(v_requested_quantity),
      true
    );

    begin
      select coalesce(array_agg(distinct value::uuid), array[]::uuid[])
      into v_option_ids
      from jsonb_array_elements_text(
        coalesce(v_item -> 'optionIds', '[]'::jsonb)
      );
    exception when others then
      raise exception 'The cart contains invalid product option data.';
    end;

    select count(*) into v_invalid_option_count
    from unnest(v_option_ids) option_id
    left join public.product_options po
      on po.id = option_id
      and po.business_id = v_business.id
      and po.product_id = v_product.id
      and po.is_active = true
    where po.id is null;

    if v_invalid_option_count > 0 then
      raise exception 'A selected product option is no longer available.';
    end if;

    if coalesce(v_product.product_type, 'standard') = 'configurable' then
      for v_group in
        select *
        from public.product_option_groups
        where business_id = v_business.id
          and product_id = v_product.id
        order by sort_order, created_at
      loop
        select count(*) into v_group_selection_count
        from public.product_options po
        where po.group_id = v_group.id
          and po.id = any(v_option_ids)
          and po.is_active = true;

        if v_group.is_required and v_group_selection_count = 0 then
          raise exception 'Please choose an option for %.', v_group.name;
        end if;

        if v_group_selection_count < v_group.min_selections
           or v_group_selection_count > v_group.max_selections then
          raise exception 'Invalid selection count for %.', v_group.name;
        end if;
      end loop;
    elsif cardinality(v_option_ids) > 0 then
      raise exception 'This product does not support configurable options.';
    end if;

    select
      coalesce(sum(po.price_adjustment), 0),
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', po.id,
            'name', po.name,
            'priceAdjustment', po.price_adjustment,
            'groupId', po.group_id,
            'groupName', pog.name
          ) order by pog.sort_order, po.sort_order, po.created_at
        ) filter (where po.id is not null),
        '[]'::jsonb
      )
    into v_option_total, v_selected_options
    from public.product_options po
    left join public.product_option_groups pog
      on pog.id = po.group_id
    where po.id = any(v_option_ids)
      and po.business_id = v_business.id
      and po.product_id = v_product.id
      and po.is_active = true;

    v_unit_price := round(
      (coalesce(v_product.selling_price, 0) + coalesce(v_option_total, 0))::numeric,
      2
    );
    v_line_subtotal := round((v_unit_price * v_quantity)::numeric, 2);
    v_subtotal := v_subtotal + v_line_subtotal;

    v_variant_label := nullif(
      concat_ws(
        ' / ',
        nullif(btrim(coalesce(v_product.color, '')), ''),
        nullif(btrim(coalesce(v_product.size, '')), '')
      ),
      ''
    );

    v_computed_items := v_computed_items || jsonb_build_array(
      jsonb_build_object(
        'productId', v_product.id,
        'productName', v_product.name,
        'quantity', v_quantity,
        'unitPrice', v_unit_price,
        'subtotal', v_line_subtotal,
        'variantLabel', v_variant_label,
        'selectedOptions', v_selected_options
      )
    );
  end loop;

  v_subtotal := round(v_subtotal::numeric, 2);
  v_total := round((v_subtotal + v_delivery_fee - v_discount)::numeric, 2);

  if v_discount > v_subtotal + v_delivery_fee then
    raise exception 'Discount cannot be greater than the order amount.';
  end if;

  if v_total < 0 then
    raise exception 'Invalid order total.';
  end if;

  if v_payment_method = 'bank_transfer' then
    v_amount_paid := v_total;
    v_remaining := 0;
    v_change := 0;
    v_payment_status := 'paid';
  elsif v_payment_method = 'deposit' then
    if v_amount_paid <= 0 or v_amount_paid >= v_total then
      raise exception 'Deposit must be greater than zero and less than the total.';
    end if;
    v_remaining := round((v_total - v_amount_paid)::numeric, 2);
    v_change := 0;
    v_payment_status := 'unpaid';
  elsif v_payment_method = 'cod' then
    if v_amount_paid > v_total then
      raise exception 'COD amount paid cannot be greater than the total.';
    end if;
    v_remaining := round(greatest(0, v_total - v_amount_paid)::numeric, 2);
    v_change := 0;
    v_payment_status := case when v_remaining <= 0 then 'paid' else 'unpaid' end;
  else
    if v_amount_paid < v_total then
      raise exception 'Amount paid must be equal to or greater than the total.';
    end if;
    v_remaining := 0;
    v_change := round(greatest(0, v_amount_paid - v_total)::numeric, 2);
    v_payment_status := 'paid';
  end if;

  v_order_number := 'POS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));

  insert into public.orders (
    owner_id,
    business_id,
    customer_id,
    order_number,
    subtotal,
    discount,
    delivery_fee,
    total,
    payment_method,
    payment_status,
    amount_paid,
    change_amount,
    remaining_balance,
    status,
    order_source,
    created_at,
    updated_at
  ) values (
    v_business.owner_id,
    v_business.id,
    p_customer_id,
    v_order_number,
    v_subtotal,
    v_discount,
    v_delivery_fee,
    v_total,
    v_payment_method,
    v_payment_status,
    v_amount_paid,
    v_change,
    v_remaining,
    'completed',
    'pos',
    now(),
    now()
  )
  returning id into v_order_id;

  for v_computed in
    select value from jsonb_array_elements(v_computed_items)
  loop
    insert into public.order_items (
      order_id,
      product_id,
      product_name,
      quantity,
      unit_price,
      subtotal,
      variant_label,
      selected_options
    ) values (
      v_order_id,
      (v_computed ->> 'productId')::uuid,
      v_computed ->> 'productName',
      (v_computed ->> 'quantity')::integer,
      (v_computed ->> 'unitPrice')::numeric,
      (v_computed ->> 'subtotal')::numeric,
      nullif(v_computed ->> 'variantLabel', ''),
      coalesce(v_computed -> 'selectedOptions', '[]'::jsonb)
    );

    update public.products
    set stock_quantity = stock_quantity - (v_computed ->> 'quantity')::integer,
        updated_at = now()
    where id = (v_computed ->> 'productId')::uuid
      and business_id = v_business.id;
  end loop;

  return jsonb_build_object(
    'order_id', v_order_id,
    'id', v_order_id,
    'order_number', v_order_number,
    'subtotal', v_subtotal,
    'discount', v_discount,
    'delivery_fee', v_delivery_fee,
    'total', v_total,
    'amount_paid', v_amount_paid,
    'remaining_balance', v_remaining,
    'change_amount', v_change,
    'payment_status', v_payment_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_order_return(p_order_id uuid, p_reason text, p_items jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_business_id uuid;
  v_order_status text;

  v_return_id uuid;
  v_return_number text;

  v_item jsonb;
  v_order_item_id uuid;
  v_return_quantity integer;

  v_product_id uuid;
  v_product_name text;
  v_sold_quantity integer;
  v_unit_price numeric(12, 2);

  v_already_returned integer;
  v_remaining_quantity integer;

  v_stock_before integer;
  v_stock_after integer;

  v_item_subtotal numeric(12, 2);
  v_refund_total numeric(12, 2) := 0;

  v_new_subtotal numeric(12, 2) := 0;
  v_discount numeric(12, 2) := 0;
  v_delivery_fee numeric(12, 2) := 0;
  v_amount_paid numeric(12, 2) := 0;
  v_new_total numeric(12, 2) := 0;
  v_new_remaining_balance numeric(12, 2) := 0;
  v_new_change_amount numeric(12, 2) := 0;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'You must be logged in.';
  end if;

  if p_reason is null
    or length(trim(p_reason)) < 3
  then
    raise exception
      'Return reason must contain at least 3 characters.';
  end if;

  if p_items is null
    or jsonb_typeof(p_items) <> 'array'
    or jsonb_array_length(p_items) = 0
  then
    raise exception
      'Select at least one item to return.';
  end if;

  /*
   * Load the order and current business.
   */
  select
    o.business_id,
    o.status
  into
    v_business_id,
    v_order_status
  from public.orders o
  where o.id = p_order_id
  for update;

  if not found then
    raise exception 'Order not found.';
  end if;

  /*
   * Check active business membership.
   */
  if not exists (
    select 1
    from public.business_members bm
    where bm.business_id = v_business_id
      and bm.user_id = v_user_id
      and bm.is_active = true
  ) then
    raise exception
      'You do not have permission to return items from this order.';
  end if;

  if v_order_status = 'cancelled' then
    raise exception
      'A cancelled order cannot be returned.';
  end if;

  if v_order_status not in (
    'new',
    'pending',
    'completed'
  ) then
    raise exception
      'Only new, pending, or completed orders can be returned.';
  end if;

  v_return_number :=
    'RET-' ||
    to_char(
      clock_timestamp(),
      'YYYYMMDD-HH24MISS'
    ) ||
    '-' ||
    upper(
      substr(
        replace(
          gen_random_uuid()::text,
          '-',
          ''
        ),
        1,
        4
      )
    );

  /*
   * Create return header.
   */
  insert into public.returns (
    business_id,
    owner_id,
    order_id,
    return_number,
    reason,
    refund_amount
  )
  values (
    v_business_id,
    v_user_id,
    p_order_id,
    v_return_number,
    trim(p_reason),
    0
  )
  returning id
  into v_return_id;

  /*
   * Process returned items.
   */
  for v_item in
    select value
    from jsonb_array_elements(p_items)
  loop
    begin
      v_order_item_id :=
        nullif(
          v_item ->> 'order_item_id',
          ''
        )::uuid;
    exception
      when others then
        raise exception
          'Invalid order item ID.';
    end;

    begin
      v_return_quantity :=
        coalesce(
          (v_item ->> 'quantity')::integer,
          0
        );
    exception
      when others then
        raise exception
          'Invalid return quantity.';
    end;

    if v_order_item_id is null then
      raise exception
        'Order item ID is required.';
    end if;

    if v_return_quantity <= 0 then
      raise exception
        'Return quantity must be greater than zero.';
    end if;

    select
      oi.product_id,
      oi.product_name,
      oi.quantity,
      oi.unit_price
    into
      v_product_id,
      v_product_name,
      v_sold_quantity,
      v_unit_price
    from public.order_items oi
    where oi.id = v_order_item_id
      and oi.order_id = p_order_id;

    if not found then
      raise exception
        'Order item was not found.';
    end if;

    select
      coalesce(
        sum(ri.quantity),
        0
      )
    into v_already_returned
    from public.return_items ri
    inner join public.returns r
      on r.id = ri.return_id
    where ri.order_item_id = v_order_item_id
      and r.business_id = v_business_id;

    v_remaining_quantity :=
      v_sold_quantity -
      v_already_returned;

    if v_remaining_quantity <= 0 then
      raise exception
        'Product "%" has already been fully returned.',
        v_product_name;
    end if;

    if v_return_quantity >
      v_remaining_quantity
    then
      raise exception
        'Cannot return product "%". Sold: %, already returned: %, maximum remaining return: %.',
        v_product_name,
        v_sold_quantity,
        v_already_returned,
        v_remaining_quantity;
    end if;

    select p.stock_quantity
    into v_stock_before
    from public.products p
    where p.id = v_product_id
      and p.business_id = v_business_id
    for update;

    if not found then
      raise exception
        'Product "%" no longer exists.',
        v_product_name;
    end if;

    v_stock_after :=
      v_stock_before +
      v_return_quantity;

    v_item_subtotal :=
      v_return_quantity *
      v_unit_price;

    v_refund_total :=
      v_refund_total +
      v_item_subtotal;

    /*
     * return_items currently uses owner_id.
     * Add business_id here only if your table has it.
     */
    insert into public.return_items (
      owner_id,
      return_id,
      order_item_id,
      product_id,
      product_name,
      quantity,
      unit_price,
      subtotal
    )
    values (
      v_user_id,
      v_return_id,
      v_order_item_id,
      v_product_id,
      v_product_name,
      v_return_quantity,
      v_unit_price,
      v_item_subtotal
    );

    update public.products
    set
      stock_quantity = v_stock_after,
      updated_at = now()
    where id = v_product_id
      and business_id = v_business_id;

    if not found then
      raise exception
        'Unable to restore stock for "%".',
        v_product_name;
    end if;

    insert into public.inventory_movements (
      business_id,
      owner_id,
      product_id,
      order_id,
      return_id,
      movement_type,
      quantity,
      stock_before,
      stock_after,
      note
    )
    values (
      v_business_id,
      v_user_id,
      v_product_id,
      p_order_id,
      v_return_id,
      'return',
      v_return_quantity,
      v_stock_before,
      v_stock_after,
      'Returned from order. Return number: ' ||
      v_return_number ||
      '. Reason: ' ||
      trim(p_reason)
    );
  end loop;

  update public.returns
  set
    refund_amount = v_refund_total
  where id = v_return_id
    and business_id = v_business_id;

  /*
   * Recalculate subtotal after returns.
   */
  select
    coalesce(
      sum(
        greatest(
          oi.quantity -
          coalesce(
            returned.total_returned,
            0
          ),
          0
        ) *
        oi.unit_price
      ),
      0
    )
  into v_new_subtotal
  from public.order_items oi
  left join (
    select
      ri.order_item_id,
      sum(ri.quantity)
        as total_returned
    from public.return_items ri
    inner join public.returns r
      on r.id = ri.return_id
    where r.order_id = p_order_id
      and r.business_id = v_business_id
    group by ri.order_item_id
  ) returned
    on returned.order_item_id = oi.id
  where oi.order_id = p_order_id;

  select
    coalesce(o.discount, 0),
    coalesce(o.delivery_fee, 0),
    coalesce(o.amount_paid, 0)
  into
    v_discount,
    v_delivery_fee,
    v_amount_paid
  from public.orders o
  where o.id = p_order_id
    and o.business_id = v_business_id;

  if not found then
    raise exception
      'Order was not found while recalculating totals.';
  end if;

  v_new_total :=
    greatest(
      0,
      v_new_subtotal -
      v_discount +
      v_delivery_fee
    );

  v_new_remaining_balance :=
    greatest(
      0,
      v_new_total -
      v_amount_paid
    );

  v_new_change_amount :=
    greatest(
      0,
      v_amount_paid -
      v_new_total
    );

  update public.orders
  set
    subtotal =
      v_new_subtotal,
    total =
      v_new_total,
    remaining_balance =
      v_new_remaining_balance,
    change_amount =
      v_new_change_amount,
    updated_at = now()
  where id = p_order_id
    and business_id = v_business_id;

  if not found then
    raise exception
      'Unable to update the order totals.';
  end if;

  return v_return_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.post_customer_credit(p_business_id uuid, p_customer_id uuid, p_type text, p_amount numeric, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_order_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account public.customer_credit_accounts%rowtype;
  v_new numeric(14,2);
  v_limit numeric(14,2);
  v_role text;
  v_order_total numeric(14,2);
  v_order_credit numeric(14,2);
begin
  if auth.uid() is null then raise exception 'Authentication required.'; end if;
  select bm.role::text into v_role from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.is_active=true limit 1;
  if v_role is null then raise exception 'Not authorized for this business.'; end if;
  if coalesce(p_amount,0)<=0 then raise exception 'Amount must be greater than zero.'; end if;
  if p_type not in ('charge','payment','adjustment_credit','adjustment_debit') then raise exception 'Invalid credit entry type.'; end if;
  if not exists(select 1 from public.customers where id=p_customer_id and business_id=p_business_id) then raise exception 'Customer not found.'; end if;

  if v_role='cashier' then
    if p_type<>'charge' or p_order_id is null then raise exception 'Cashiers can only post credit from a POS sale.'; end if;
    select total,coalesce(credit_amount,0) into v_order_total,v_order_credit from public.orders where id=p_order_id and business_id=p_business_id and customer_id=p_customer_id for update;
    if not found then raise exception 'Credit order not found.'; end if;
    if v_order_credit<>0 then raise exception 'Credit was already posted for this order.'; end if;
    if round(p_amount::numeric,2)<>round(v_order_total::numeric,2) then raise exception 'Credit amount must match the trusted order total.'; end if;
  elsif v_role not in ('owner','admin','manager') then
    raise exception 'You do not have permission to update customer credit.';
  end if;

  insert into public.customer_credit_accounts(business_id,customer_id) values(p_business_id,p_customer_id) on conflict(business_id,customer_id) do nothing;
  select * into v_account from public.customer_credit_accounts where business_id=p_business_id and customer_id=p_customer_id for update;
  v_limit:=coalesce(v_account.credit_limit,0);
  if p_type in ('charge','adjustment_debit') then v_new:=v_account.balance+p_amount; else v_new:=greatest(0,v_account.balance-p_amount); end if;
  if p_type='charge' and v_limit>0 and v_new>v_limit then raise exception 'Customer credit limit exceeded.'; end if;
  update public.customer_credit_accounts set balance=round(v_new::numeric,2),updated_at=now() where business_id=p_business_id and customer_id=p_customer_id;
  insert into public.customer_credit_ledger(business_id,customer_id,order_id,entry_type,amount,balance_after,note,reference,created_by)
    values(p_business_id,p_customer_id,p_order_id,p_type,round(p_amount::numeric,2),round(v_new::numeric,2),nullif(btrim(coalesce(p_note,'')),''),nullif(btrim(coalesce(p_reference,'')),''),auth.uid());
  if p_order_id is not null and p_type='charge' then update public.orders set credit_amount=credit_amount+round(p_amount::numeric,2) where id=p_order_id and business_id=p_business_id and customer_id=p_customer_id; end if;
  return jsonb_build_object('balance',round(v_new::numeric,2),'creditLimit',v_limit);
end;
$function$

CREATE OR REPLACE FUNCTION public.receive_purchase_order(p_purchase_order_id uuid, p_receipts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_po public.purchase_orders%rowtype;
  v_item jsonb;
  v_po_item public.purchase_order_items%rowtype;
  v_product public.products%rowtype;
  v_qty integer;
  v_before integer; v_branch_before integer;
  v_after integer;
  v_remaining integer;
  v_total_received integer := 0;
  v_all_received boolean;
begin
  if v_user is null then raise exception 'Authentication required.'; end if;
  if p_receipts is null or jsonb_typeof(p_receipts) <> 'array' or jsonb_array_length(p_receipts) = 0 then
    raise exception 'Add at least one received quantity.';
  end if;

  select * into v_po from public.purchase_orders where id = p_purchase_order_id for update;
  if not found then raise exception 'Purchase order not found.'; end if;
  if v_po.status in ('received','cancelled') then raise exception 'This purchase order cannot receive more stock.'; end if;

  perform public.tenh_assert_effective_permission(v_po.business_id,'purchases.update');
  if v_po.location_id is distinct from public.tenh_request_branch(v_po.business_id) then raise exception 'Purchase order belongs to another branch.';end if;

  for v_item in select value from jsonb_array_elements(p_receipts)
  loop
    begin
      v_qty := (v_item->>'quantity')::integer;
    exception when others then
      raise exception 'Invalid received quantity.';
    end;
    if v_qty is null or v_qty <= 0 then raise exception 'Received quantity must be greater than zero.'; end if;

    select * into v_po_item
    from public.purchase_order_items
    where id = (v_item->>'itemId')::uuid
      and purchase_order_id = v_po.id
      and business_id = v_po.business_id
    for update;
    if not found then raise exception 'Purchase order line not found.'; end if;

    v_remaining := v_po_item.ordered_quantity - v_po_item.received_quantity;
    if v_qty > v_remaining then raise exception 'Received quantity exceeds remaining quantity for %.', v_po_item.product_name; end if;

    select * into v_product from public.products
    where id = v_po_item.product_id and business_id = v_po.business_id for update;
    if not found then raise exception 'Product no longer exists.'; end if;

    v_before := coalesce(v_product.stock_quantity,0);
    v_after := v_before + v_qty;

    update public.products
      set stock_quantity = v_after,
          updated_at = now()
    where id = v_product.id;

    select quantity into v_branch_before from public.product_location_stock where business_id=v_po.business_id and location_id=v_po.location_id and product_id=v_product.id for update;
    if not found then raise exception 'Assign this product to the branch before receiving stock.';end if;
    update public.product_location_stock set quantity=quantity+v_qty,updated_at=now() where business_id=v_po.business_id and location_id=v_po.location_id and product_id=v_product.id;
    update public.branch_product_details set cost_price=v_po_item.unit_cost,updated_at=now() where business_id=v_po.business_id and location_id=v_po.location_id and id=v_product.id;
    perform set_config('tenh.adjustment_branch',v_po.location_id::text,true);
    update public.purchase_order_items
      set received_quantity = received_quantity + v_qty, updated_at = now()
    where id = v_po_item.id;

    insert into public.stock_adjustments (
      business_id, product_id, adjustment_type, quantity_delta,
      stock_before, stock_after, reason, reference, created_by
    ) values (
      v_po.business_id, v_product.id, 'increase', v_qty,
      v_branch_before, v_branch_before+v_qty, 'Purchase order receipt', v_po.po_number, v_user
    );

    v_total_received := v_total_received + v_qty;
  end loop;

  select bool_and(received_quantity >= ordered_quantity)
    into v_all_received
  from public.purchase_order_items
  where purchase_order_id = v_po.id;

  update public.purchase_orders
    set status = case when coalesce(v_all_received,false) then 'received' else 'partial' end,
        updated_at = now()
  where id = v_po.id;

  perform set_config('tenh.adjustment_branch','',true);
  return jsonb_build_object('purchaseOrderId', v_po.id, 'receivedQuantity', v_total_received, 'status', case when coalesce(v_all_received,false) then 'received' else 'partial' end);
end;
$function$

CREATE OR REPLACE FUNCTION public.tenh_assert_plan_branch(p_business_id uuid, p_location_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform 1 from public.businesses where id = p_business_id for update;

  if public.tenh_subscription_is_expired_now(p_business_id) then
    raise exception 'Subscription expired. Reactivate the subscription before using the workspace.';
  end if;

  if not exists(
    select 1
    from public.business_locations
    where business_id = p_business_id
      and id = p_location_id
      and is_active
  ) then
    raise exception 'Choose an active branch in this business.';
  end if;

  if (
    select count(*)
    from public.business_locations
    where business_id = p_business_id
      and is_active
  ) > public.tenh_branch_limit(p_business_id) then
    raise exception 'Active branches exceed the subscription. Deactivate unused branches or upgrade.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.tenh_coupon_quote(p_business uuid, p_branch uuid, p_channel text, p_code text, p_lines jsonb, p_customer uuid, p_check_customer boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.business_coupons%rowtype; subtotal numeric; eligible numeric; discount numeric; enabled boolean;
begin
 if p_channel='pos' then
   select enable_coupons into enabled from public.branch_pos_settings where business_id=p_business and location_id=p_branch for share;
 else
   select enable_coupons into enabled from public.business_storefronts where business_id=p_business for share;
 end if;
 if not coalesce(enabled,false) then raise exception 'Coupon codes are disabled for this channel.';end if;
 select * into c from public.business_coupons where business_id=p_business and location_id=p_branch
 and upper(code)=upper(btrim(p_code)) and is_active and not is_automatic
 and ((p_channel='pos' and apply_pos) or (p_channel='online' and apply_online))
 and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()) for update;
 if not found then raise exception 'This coupon is invalid or expired.';end if;
 select coalesce(sum((l->>'subtotal')::numeric),0),coalesce(sum((l->>'subtotal')::numeric)
 filter(where c.product_ids is null or (l->>'productId')::uuid=any(c.product_ids)),0)
 into subtotal,eligible from jsonb_array_elements(p_lines) l;
 if subtotal<c.minimum_order then raise exception 'This coupon requires a minimum order of %.',c.minimum_order;end if;
 if eligible<=0 then raise exception 'Add an eligible product to use this coupon.';end if;
 if c.usage_limit is not null and c.usage_count>=c.usage_limit then raise exception 'This coupon has reached its usage limit.';end if;
 if c.per_customer_limit is not null and p_check_customer then
  if p_customer is null then raise exception 'Select a customer to use this limited coupon.';end if;
  if (select count(*) from public.coupon_redemptions where coupon_id=c.id and customer_id=p_customer)>=c.per_customer_limit
   then raise exception 'This customer has reached the coupon usage limit.';end if;
 end if;
 discount:=least(eligible,coalesce(c.max_discount,eligible),case when c.discount_type='percentage' then round(eligible*c.discount_value/100,2) else c.discount_value end);
 return jsonb_build_object('id',c.id,'code',c.code,'discount',discount);
end$function$

CREATE OR REPLACE FUNCTION public.tenh_create_order_return_accounted(p_order_id uuid, p_reason text, p_items jsonb, p_refund_method text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare result jsonb;
begin
 if p_refund_method not in ('cash','bank_transfer','other') or p_refund_method is null then raise exception 'Choose the refund payment method.'; end if;
 perform set_config('tenh.refund_method',p_refund_method,true);
 select to_jsonb(create_order_return(p_order_id,p_reason,p_items)) into result;
 perform set_config('tenh.refund_method','',true);
 return result;
end; $function$

CREATE OR REPLACE FUNCTION public.tenh_operating_product(p_product products)
 RETURNS products
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b uuid; details public.products;
begin
 b:=public.tenh_request_branch(p_product.business_id);
 if b is null then raise exception 'Choose an operating branch.';end if;
 select (jsonb_populate_record(null::public.products,to_jsonb(d)-'location_id')).* into details from public.branch_product_details d
 where d.business_id=p_product.business_id and d.id=p_product.id and d.location_id=b and not d.branch_archived;
 if not found or not details.is_active or not coalesce(details.is_pos,true) then raise exception 'Product is unavailable in this branch.';end if;
 details.stock_quantity:=p_product.stock_quantity;
 return details;
end$function$

CREATE OR REPLACE FUNCTION public.tenh_pos_guard(p_business_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text; v_b jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Please sign in again.' USING ERRCODE='42501'; END IF;
  SELECT m.role::text INTO v_role
  FROM public.business_members m
  WHERE m.business_id=p_business_id AND m.user_id=auth.uid()
    AND m.is_active=true AND coalesce(m.team_password_required,false)=false
  FOR SHARE;
  IF v_role IS NULL OR NOT public.tenh_user_permission_allowed(p_business_id,auth.uid(),'pos.access') THEN
    RAISE EXCEPTION 'You do not have Point of Sale access.' USING ERRCODE='42501';
  END IF;
  IF EXISTS(
    SELECT 1 FROM public.profiles p
    WHERE p.id=auth.uid() AND coalesce((to_jsonb(p)->>'is_active')::boolean,true)=false
  ) THEN RAISE EXCEPTION 'This account has been disabled.' USING ERRCODE='42501'; END IF;
  SELECT to_jsonb(b) INTO v_b FROM public.businesses b WHERE b.id=p_business_id FOR SHARE;
  IF v_b IS NULL OR coalesce((v_b->>'is_active')::boolean,false)=false
    OR coalesce(v_b->>'subscription_status','') IN ('expired','trial_pending','trial_blocked')
    OR (nullif(v_b->>'subscription_expires_at','') IS NOT NULL AND (v_b->>'subscription_expires_at')::timestamptz<=now())
    OR (v_b->>'subscription_status'='trialing' AND nullif(v_b->>'trial_expires_at','') IS NOT NULL AND (v_b->>'trial_expires_at')::timestamptz<=now()) THEN
    RAISE EXCEPTION 'The business subscription does not allow POS sales.' USING ERRCODE='42501';
  END IF;
  RETURN v_role;
END;
$function$

CREATE OR REPLACE FUNCTION public.tenh_pos_priced_product(p_product products)
 RETURNS products
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.products;
begin
 result:=public.tenh_operating_product(p_product);
 result.selling_price:=public.tenh_product_sale_price(result.business_id,public.tenh_request_branch(result.business_id),'pos',result.id,result.selling_price);
 return result;
end$function$

CREATE OR REPLACE FUNCTION public.tenh_request_branch(p_business uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  h jsonb:=coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
  requested uuid;
  membership_role text;
  assigned uuid;
  header_business uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in again.' USING ERRCODE='42501';
  END IF;

  SELECT m.role::text,m.default_location_id
    INTO membership_role,assigned
  FROM public.business_members m
  WHERE m.business_id=p_business
    AND m.user_id=auth.uid()
    AND m.is_active=true
    AND coalesce(m.team_password_required,false)=false
  LIMIT 1;

  IF membership_role IS NULL THEN
    RAISE EXCEPTION 'Business access is unavailable.' USING ERRCODE='42501';
  END IF;

  IF nullif(h->>'x-tenh-business-id','') IS NOT NULL THEN
    BEGIN
      header_business:=(h->>'x-tenh-business-id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Invalid business context.' USING ERRCODE='42501';
    END;
    IF header_business IS DISTINCT FROM p_business THEN
      RAISE EXCEPTION 'Invalid business context.' USING ERRCODE='42501';
    END IF;
  END IF;

  IF nullif(h->>'x-tenh-branch-id','') IS NOT NULL THEN
    BEGIN
      requested:=(h->>'x-tenh-branch-id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'Invalid operating branch.' USING ERRCODE='42501';
    END;
  END IF;

  -- Set only inside the checked online-order action; never accepted from HTTP headers.
  IF nullif(current_setting('tenh.online_order_scope',true),'') IS NOT NULL THEN
    SELECT o.location_id INTO requested FROM public.orders o
    JOIN public.business_locations l ON l.id=o.location_id AND l.business_id=o.business_id AND l.is_active AND NOT l.plan_disable_pending
    WHERE o.id=current_setting('tenh.online_order_scope')::uuid AND o.business_id=p_business AND o.order_source='online'
      AND public.tenh_receive_all_online_orders(p_business)
      AND public.tenh_user_permission_allowed(p_business,auth.uid(),'orders.view');
    IF requested IS NULL THEN RAISE EXCEPTION 'Online order access is unavailable.' USING ERRCODE='42501'; END IF;
    RETURN requested;
  END IF;

  IF membership_role='owner' THEN
    IF requested IS NULL THEN RETURN NULL; END IF;
    IF NOT EXISTS(
      SELECT 1 FROM public.business_locations l
      WHERE l.id=requested AND l.business_id=p_business AND l.is_active=true
    ) THEN
      RAISE EXCEPTION 'Invalid operating branch.' USING ERRCODE='42501';
    END IF;
    RETURN requested;
  END IF;

  IF assigned IS NULL OR NOT EXISTS(
    SELECT 1 FROM public.business_locations l
    WHERE l.id=assigned AND l.business_id=p_business AND l.is_active=true
  ) THEN
    RAISE EXCEPTION 'Your assigned branch is unavailable. Ask the Owner to assign an active branch.' USING ERRCODE='42501';
  END IF;

  IF requested IS NOT NULL AND requested IS DISTINCT FROM assigned THEN
    RAISE EXCEPTION 'This branch is not assigned to your account.' USING ERRCODE='42501';
  END IF;
  RETURN assigned;
END;
$function$

CREATE OR REPLACE FUNCTION public.tenh_user_permission_allowed(p_business uuid, p_user uuid, p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text; member uuid; override_value boolean;
begin
 select m.role::text,m.id into r,member from public.business_members m
 where m.business_id=p_business and m.user_id=p_user and m.is_active and not coalesce(m.team_password_required,false);
 if r is null then return false; end if;
 if r='owner' then return true; end if;
 select enabled into override_value from public.business_member_permissions where member_id=member and permission=p_permission;
 if found then return override_value; end if;
 if r in ('manager','staff','cashier') then
  select enabled into override_value from public.branch_role_permissions where business_id=p_business and location_id=(select default_location_id from public.business_members where id=member) and role=r and permission=p_permission;
  if found then return override_value; end if;
 end if;
 return public.tenh_default_role_permission(r,p_permission);
end; $function$

CREATE OR REPLACE FUNCTION public.tenh_users_actor_branch(p_business uuid, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; b uuid;
BEGIN
 SELECT role::text,default_location_id INTO r,b FROM public.business_members
 WHERE business_id=p_business AND user_id=p_actor AND is_active AND NOT team_password_required LIMIT 1;
 IF r IS NULL THEN RAISE EXCEPTION 'Business access is unavailable.' USING ERRCODE='42501'; END IF;
 IF r='owner' THEN RETURN NULL; END IF;
 IF b IS NULL OR NOT EXISTS(SELECT 1 FROM public.business_locations WHERE id=b AND business_id=p_business AND is_active) THEN
  RAISE EXCEPTION 'Your assigned branch is unavailable. Ask the Owner to assign an active branch.' USING ERRCODE='42501';
 END IF;
 RETURN b;
END;
$function$

CREATE OR REPLACE FUNCTION public.tenh_users_guard(p_business uuid, p_actor uuid, p_write boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.businesses%rowtype; r text; allowed boolean;
BEGIN
 IF p_actor IS NULL THEN RAISE EXCEPTION 'Sign in again.' USING ERRCODE='42501'; END IF;
 IF p_write THEN SELECT * INTO b FROM public.businesses WHERE id=p_business FOR UPDATE;
 ELSE SELECT * INTO b FROM public.businesses WHERE id=p_business; END IF;
 IF NOT FOUND OR b.is_active IS DISTINCT FROM true THEN RAISE EXCEPTION 'Business access is unavailable.' USING ERRCODE='42501'; END IF;
 SELECT role::text INTO r FROM public.business_members
  WHERE business_id=p_business AND user_id=p_actor AND is_active AND NOT team_password_required;
 IF r IS NULL THEN RAISE EXCEPTION 'User management permission required.' USING ERRCODE='42501'; END IF;
 IF p_write THEN
  allowed:=public.tenh_user_permission_allowed(p_business,p_actor,'users.create')
    OR public.tenh_user_permission_allowed(p_business,p_actor,'users.create_limited')
    OR public.tenh_user_permission_allowed(p_business,p_actor,'users.update_role')
    OR public.tenh_user_permission_allowed(p_business,p_actor,'users.delete');
 ELSE
  allowed:=public.tenh_user_permission_allowed(p_business,p_actor,'users.view');
 END IF;
 IF NOT allowed THEN RAISE EXCEPTION 'User management permission required.' USING ERRCODE='42501'; END IF;
 IF p_write AND (coalesce(b.subscription_status,'active')<>'active' OR (b.subscription_expires_at IS NOT NULL AND b.subscription_expires_at<=now())) THEN
  RAISE EXCEPTION 'An active paid subscription is required to manage team access.' USING ERRCODE='42501';
 END IF;
 RETURN r;
END;
$function$

CREATE OR REPLACE FUNCTION public.tenh_users_validate_branch(p_business uuid, p_branch uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.businesses%rowtype; n integer; lim integer;
BEGIN
 SELECT * INTO b FROM public.businesses WHERE id=p_business;
 IF NOT EXISTS(SELECT 1 FROM public.business_locations WHERE business_id=p_business AND id=p_branch AND is_active) THEN RAISE EXCEPTION 'Choose an active starting branch in this business.'; END IF;
 lim:=CASE WHEN b.subscription_plan_key='custom' AND b.subscription_status='active' THEN greatest(1,coalesce((to_jsonb(b)->>'subscription_branch_limit')::integer,1)) ELSE 1 END;
 SELECT count(*) INTO n FROM public.business_locations WHERE business_id=p_business AND is_active;
 IF n>lim THEN RAISE EXCEPTION 'Active branches exceed your plan. Review branch subscription limits first.'; END IF;
END;
$function$
